from pysat.solvers import Glucose3

# Sudoku SAT encoding
# Variable x[i][j][d] = True means cell (i,j) contains digit d
# We'll encode as SAT variable: (i*9 + j)*9 + (d-1) + 1

def var(i, j, d):
    """Return SAT variable number for cell (i,j) having digit d (1-9)"""
    return (i * 9 + j) * 9 + d  # d is 1-indexed

solver = Glucose3()

# 1. Each cell contains at least one digit
for i in range(9):
    for j in range(9):
        solver.add_clause([var(i, j, d) for d in range(1, 10)])

# 2. Each cell contains at most one digit
for i in range(9):
    for j in range(9):
        for d1 in range(1, 10):
            for d2 in range(d1+1, 10):
                solver.add_clause([-var(i, j, d1), -var(i, j, d2)])

# 3. Each row contains each digit at least once
for i in range(9):
    for d in range(1, 10):
        solver.add_clause([var(i, j, d) for j in range(9)])

# 4. Each column contains each digit at least once
for j in range(9):
    for d in range(1, 10):
        solver.add_clause([var(i, j, d) for i in range(9)])

# 5. Each 3x3 block contains each digit at least once
for bi in range(3):
    for bj in range(3):
        for d in range(1, 10):
            cells = [var(bi*3 + di, bj*3 + dj, d) 
                     for di in range(3) for dj in range(3)]
            solver.add_clause(cells)

# Fixed assignments (index in row-major order -> (row, col, value))
fixed = {
    2: 3, 11: 6, 13: 8, 20: 9, 22: 2, 35: 7,
    42: 2, 46: 9, 50: 4, 57: 6, 58: 4, 60: 9,
    62: 8, 69: 5, 78: 6, 79: 4
}

for idx, val in fixed.items():
    i, j = idx // 9, idx % 9
    solver.add_clause([var(i, j, val)])

# Solve
if solver.solve():
    model = solver.get_model()
    model_set = set(model)

    grid = []
    for i in range(9):
        for j in range(9):
            for d in range(1, 10):
                if var(i, j, d) in model_set:
                    grid.append(d)
                    break

    print("Solution found!")
    print(grid)
    print("\nGrid visualization:")
    for i in range(9):
        row = grid[i*9:(i+1)*9]
        print(row)

    # Verify fixed assignments
    print("\nVerifying fixed assignments:")
    all_ok = True
    for idx, val in fixed.items():
        if grid[idx] != val:
            print(f"  MISMATCH at index {idx}: expected {val}, got {grid[idx]}")
            all_ok = False
    if all_ok:
        print("  All fixed assignments satisfied!")
else:
    print("UNSATISFIABLE")

grid = [4, 2, 3, 9, 7, 6, 1, 8, 5, 5, 7, 6, 4, 8, 1, 3, 2, 9, 8, 1, 9, 5, 2, 3, 7, 6, 4, 3, 8, 5, 1, 6, 2, 4, 9, 7, 7, 6, 4, 8, 3, 9, 2, 5, 1, 2, 9, 1, 7, 5, 4, 8, 3, 6, 1, 3, 2, 6, 4, 5, 9, 7, 8, 6, 4, 7, 3, 9, 8, 5, 1, 2, 9, 5, 8, 2, 1, 7, 6, 4, 3]

# Verify rows, columns, blocks
valid = True
for i in range(9):
    row = grid[i*9:(i+1)*9]
    if sorted(row) != list(range(1,10)):
        print(f"Row {i} invalid: {row}"); valid = False

for j in range(9):
    col = [grid[i*9+j] for i in range(9)]
    if sorted(col) != list(range(1,10)):
        print(f"Col {j} invalid: {col}"); valid = False

for bi in range(3):
    for bj in range(3):
        block = [grid[(bi*3+di)*9 + bj*3+dj] for di in range(3) for dj in range(3)]
        if sorted(block) != list(range(1,10)):
            print(f"Block ({bi},{bj}) invalid: {block}"); valid = False

print("All constraints satisfied!" if valid else "INVALID SOLUTION")
